const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · Lead finder</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software is a fictional company · business details come from public Google Maps listings (via SerpAPI), the AI score is a suggestion, and nothing is ever sent to the businesses.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that lead list</h1><p class="muted">The link may be old (results are kept for 7 days). Run a new search below.</p><a class="btn" href="${BASE}">Open the lead finder</a></div>`);
// ---- end shared helpers ----

// Result page: the scored lead list for one search
const t = String(($json.query || {}).t || '').slice(0, 40);
const store = $getWorkflowStaticData('global');
const r = (store.runs || {})[t];
if (!r) return [{ json: { html: notFoundPage() } }];
if (r.status !== 'done') return [{ json: { html: page('Still working', `<div class="card"><h1>Still working on it</h1><p class="muted">The lead finder is visiting websites and scoring. Refresh this page in a few seconds.</p><a class="btn" href="${BASE}/result?t=${r.token}">Refresh</a></div>`) } }];
const s = r.stats || {};
const sig = (x) => { const cls = /No website|did not answer/.test(x) ? 'bad' : /booking|chat|WhatsApp/i.test(x) ? 'warn' : /Instagram|Facebook|LinkedIn|Contact form/.test(x) ? 'good' : ''; return `<span class="sig ${cls}">${esc(x)}</span>`; };
const rows = r.leads.map((l, i) => {
  const seg = SEG[l.segment] || SEG.cold;
  const contact = [l.phone ? esc(l.phone) : '', l.website ? `<a href="${esc(l.website)}" target="_blank" rel="noopener">${esc(domain(l.website))}</a>` : '<span class="muted">no website</span>', ...l.emails.map((e) => `<span class="sig good">${esc(e)}</span>`)].filter(Boolean).join('<br>');
  return `<tr class="lead"><td class="rank">${i + 1}</td><td><div class="nm">${esc(l.name)}</div><div class="muted small">${esc(l.category)}${l.rating ? ` · ${l.rating}★ (${l.reviews})` : ''}</div><div class="small muted">${esc(l.address)}</div>${l.maps ? `<a class="small" href="${esc(l.maps)}" target="_blank" rel="noopener">Google Maps</a>` : ''}</td><td class="small">${contact}</td><td>${l.signals.map(sig).join('')}</td><td style="min-width:220px"><span class="st ${seg[1]}">${seg[0]} · ${l.fit}</span><div class="scorebar ${l.segment}"><i style="width:${l.fit}%"></i></div><div class="why">${esc(l.why)}</div>${l.opening ? `<div class="line">“${esc(l.opening)}”</div>` : ''}<div class="small muted" style="margin-top:4px">Best channel: ${esc(l.channel || '')}</div></td></tr>`;
}).join('');
const body = `<div class="card"><span class="st st-info">Lead list</span> <span class="st st-ok">${r.leads.length} businesses</span> ${r.cached ? '<span class="st st-wait">from the 7-day cache</span>' : '<span class="st st-wait">fresh from Google Maps</span>'}
<h1>${esc(r.what)} in ${esc(r.where)}</h1>
<p class="muted">Scored for: <b>${esc(r.offer)}</b></p>
<div class="chips"><span class="chip">🔥 ${s.hot || 0} hot</span><span class="chip">${s.warm || 0} warm</span><span class="chip">${s.cold || 0} cold</span><span class="chip">${s.sites || 0} with a website</span><span class="chip">${s.emails || 0} emails found</span><span class="chip">${s.booking || 0} already book online</span></div>
<div class="kv"><div>Scored by<b>${esc(r.scoredBy)}</b></div><div>Time taken<b>${r.seconds} s</b></div><div>Saved to<b>Google Sheets · Leads tab</b></div></div>
<p style="margin-top:14px"><a class="btn" href="${BASE}/csv?t=${r.token}">Download CSV</a> <a class="btn alt" href="${BASE}">Search again</a></p></div>
<div class="card" style="overflow-x:auto"><table><tr><th>#</th><th>Business</th><th>Contact</th><th>Found on their website</th><th>AI fit for your offer</th></tr>${rows || '<tr><td colspan="5">No businesses found for this search.</td></tr>'}</table></div>
<div class="card"><h2>What the automation just did</h2><ul class="steps">
<li><span class="ok">✓</span><span>Pulled ${r.leads.length} listings from <b>Google Maps</b>${r.cached ? ' (cached from an earlier search)' : ' (live, via SerpAPI)'}</span></li>
<li><span class="ok">✓</span><span>Visited ${Math.min(12, s.sites || 0)} websites and found ${s.emails || 0} email addresses plus booking, chat, WhatsApp and social signals</span></li>
<li><span class="ok">✓</span><span><b>Google Gemini</b> scored each business for "${esc(r.offer)}", explained why and wrote an opening line</span></li>
<li><span class="ok">✓</span><span>Wrote ${r.leads.length} rows to <b>Google Sheets</b> and prepared the CSV</span></li></ul>
<p class="small muted" style="margin-top:10px">Nothing was sent to these businesses. Scores are suggestions to prioritise outreach; always check before contacting anyone.</p></div>`;
return [{ json: { html: page(`${r.what} in ${r.where} – AI lead finder`, body, true) } }];

// CSV download for one search
const t = String(($json.query || {}).t || '').slice(0, 40);
const store = $getWorkflowStaticData('global');
const r = (store.runs || {})[t];
const q = (v) => '"' + String(v ?? '').replace(/"/g, '""') + '"';
const head = ['Rank', 'Business', 'Category', 'Rating', 'Reviews', 'Address', 'Phone', 'Website', 'Emails found', 'Website signals', 'AI fit score', 'Segment', 'Why', 'Opening line', 'Best channel', 'Google Maps'];
const rows = r && r.status === 'done' ? r.leads.map((l, i) => [i + 1, l.name, l.category, l.rating ?? '', l.reviews, l.address, l.phone, l.website, l.emails.join(' '), l.signals.join('; '), l.fit, l.segment, l.why, l.opening, l.channel, l.maps]) : [];
const csv = '﻿' + [head, ...rows].map((row) => row.map(q).join(',')).join('\r\n');
const slug = r ? (r.what + '-' + r.where).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') : 'leads';
return [{ json: { csv, file: 'leads-' + slug + '.csv' } }];

