// Owner view: searches from the last 7 days and the demo's usage
const store = $getWorkflowStaticData('global');
const runs = Object.values(store.runs || {}).sort((a, b) => b.createdAt - a.createdAt);
const day = store.day || { live: 0, runs: 0 }, month = store.month || { live: 0 };
const n = (f) => runs.filter(f).length;
const rows = runs.map((r) => { const s = r.stats || {}; return `<tr><td>${new Date(r.createdAt).toLocaleString('en-GB', { timeZone: 'Europe/London', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' })}</td><td><b>${esc(r.what)}</b> in ${esc(r.where)}<br><span class="muted small">${esc(r.offer)}</span></td><td>${r.status === 'done' ? r.leads.length : esc(r.status)}${r.cached ? '<br><span class="muted small">cache</span>' : '<br><span class="muted small">live</span>'}</td><td>${s.hot ?? '–'} / ${s.warm ?? '–'} / ${s.cold ?? '–'}</td><td>${s.emails ?? '–'}</td><td>${r.seconds ?? '–'} s</td><td><a href="${BASE}/result?t=${r.token}" target="_blank">list</a> · <a href="${BASE}/csv?t=${r.token}">csv</a></td></tr>`; }).join('');
const body = `<h1>Lead finder – owner view</h1><p class="muted">Last 7 days · ${new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' })} UK</p>
<div class="kpis"><div class="kpi"><b>${runs.length}</b>Searches (7 days)</div><div class="kpi"><b>${runs.reduce((a, r) => a + (r.leads ? r.leads.length : 0), 0)}</b>Leads listed</div><div class="kpi"><b>${runs.reduce((a, r) => a + ((r.stats || {}).hot || 0), 0)}</b>Hot leads</div><div class="kpi"><b>${day.live} / 10</b>Live searches today</div><div class="kpi"><b>${month.live} / 200</b>Live searches this month</div><div class="kpi"><b>${Object.keys(store.cache || {}).length}</b>Cached places</div></div>
<div class="card" style="overflow-x:auto"><table><tr><th>When</th><th>Search</th><th>Leads</th><th>Hot / warm / cold</th><th>Emails</th><th>Time</th><th>Open</th></tr>${rows || '<tr><td colspan="7">Nothing yet.</td></tr>'}</table></div>
<p class="small muted">Full log: <a href="https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit" target="_blank">Google Sheets (Leads tab)</a> · SerpAPI free plan: 250 searches a month; the demo caps itself at 10 live searches a day and 200 a month, cached places cost nothing.</p>`;
return [{ json: { html: page('Lead finder – owner view', body, true) } }];
